head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.initIsurCd = "";      // 첫 조회 뒤 한 번만 고를 부모의 현재 발행기관코드 (AS-IS arr[0] → strSch, 원본은 쓰이지 않던 의도 — §8 #2)

// 원본 : ULDSTF05108.xml (W-Craft 변환본 + API 적용 개발 사본, 원본 ULDSTF05108.gfm 은 저장소에 없음)
/*
 * 화면 동작
 *  - 부모(ULDSTF05101 예비심사관리)가 넘긴 증권그룹·시장구분으로 종류주식 예비심사 대상 발행기관을 조회한다.
 *    열리면 바로 조회하고, 발행기관명·코드로 다시 조회할 수 있다. 첫 조회에서는 부모의 현재 발행기관 행을 고른다.
 *  - 행을 더블클릭하면 고른 법인을 부모에 돌려주고 닫는다(창 닫기 = 취소).
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF05108/ULDSTF05108.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다. (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05108.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 파라미터 수신 → Enter 키 바인딩 → 발행기관 목록 조회. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 파라미터 수신 — 원본은 부모 scwin.fn_GetPar(=fn_GetParIsur)를 빌려 arr 로 받았다 (§1.2)
    //    comNm·searchType 도 계약상 넘어오지만 원본처럼 조회 조건에 쓰지 않는다 (§10 #1)
    const param = $c.data.getParameter() ?? {};
    scwin.initIsurCd = param.isurCd ?? "";                      // AS-IS arr[0]
    dma_search.set("secugrpId", param.secugrpId ?? "");         // AS-IS arr[2]
    dma_search.set("spotIsuTrdMktTpCd", param.mktTpCd ?? "");   // AS-IS arr[3]

    // 2) 조회 영역 Enter 키 (규칙 22) — 원본 txb_COM_NM_onkeydown(keyCode 13)
    $c.win.setEnterKeyEvent(grp_search, scwin.img_Search_onclick);

    // 3) 열리면 바로 조회
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description [조회] — 발행기관명·코드로 다시 조회한다. (원본 img_Search_onclick — §4)
 * @returns
 * @hidden N
 */
scwin.img_Search_onclick = async function () {
    try {
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05108.img_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_IsuInst_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록 더블클릭 — 고른 법인을 부모에 돌려주고 닫는다. (원본 grd_IsuInst_OnDblClick — §4)
 * @param {Number} rowIndex 행 번호
 * @param {Number} columnIndex 열 번호
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.returnIsur(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05108.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 발행기관 목록 조회 — GET select-list-prelisting-kindstk(isurCd·comNm·secugrpId·spotIsuTrdMktTpCd) → dlt_isurInstRes,
 * 건수 표시, 첫 조회면 부모의 현재 발행기관 행을 고른다. (원본 fn_list_sync — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectList = async function () {
    // 원본은 ref 에 응답 dataList(dlt_isurInstRes)를 주고 요청은 requestData 로 따로 넘겼다 → 요청 dataMap 하나로 정리 (§8 #3)
    const sbmOptions = {
        id : "sbm_selectListPreListingKindstk",
        action : "/api/listing/common/pop/issur/select-list-prelisting-kindstk",
        method : "get",
        ref : "dma_search",
        target : "dlt_isurInstRes=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res?.skipped) return;   // 진행 중 조회가 있어 이번 호출은 건너뜀

    txb_TotCnt.setValue(dlt_isurInstRes.getRowCount());
    scwin.focusInitIsur();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.focusInitIsur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 첫 조회 한 번만 — 부모의 현재 발행기관 행이 목록에 있으면 그 행을 고른다. (원본 fn_list_sync 의 strCdSch 루프 의도 — §8 #2)
 * @returns
 * @hidden N
 */
scwin.focusInitIsur = function () {
    if ($c.util.isEmpty(scwin.initIsurCd)) return;

    const rowCount = dlt_isurInstRes.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        if (dlt_isurInstRes.getCellData(i, "isurCd") === scwin.initIsurCd) {
            grd_IsuInst.setFocusedCell(i, 0);
            break;
        }
    }
    scwin.initIsurCd = "";
};

/**
 * @method
 * @name scwin.returnIsur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 고른 법인을 반환 계약 키(camelCase)로 부모에 돌려주고 닫는다. 원본의 closePopup 이중 호출은 하나로 고쳤다. (§1.2 반환 규약, §8 #4)
 * @param {Number} rowIndex 행 번호
 * @returns
 * @hidden N
 */
scwin.returnIsur = async function (rowIndex) {
    const row = dlt_isurInstRes.getRowJSON(rowIndex);

    await $c.win.closePopup({
        isurCd : row.isurCd ?? "",          // AS-IS ISUR_CD
        comNm : row.comNm ?? "",            // AS-IS COM_NM
        listDd : row.listDd ?? "",          // AS-IS LIST_DD
        listBzSeq : row.listBzSeq ?? "",    // AS-IS LIST_BZ_SEQ
        dbClickYn : "Y"                     // AS-IS DBCLICKYN
    });
};
